#!/usr/bin/env bash
# Writes Sources/ClaudioControlProtocol/BuildInfo.swift from VERSION and git. Idempotent: only rewrites on change.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
VERSION="${CLAUDIO_VERSION:-$(cat "$ROOT/VERSION")}"
BUILD="${CLAUDIO_BUILD:-$(git -C "$ROOT" rev-list --count HEAD 2>/dev/null || echo 0)}"
SHA="${CLAUDIO_SHA:-$(git -C "$ROOT" rev-parse --short HEAD 2>/dev/null || echo unknown)}"
DATE="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
OUT="$ROOT/Sources/ClaudioControlProtocol/BuildInfo.swift"
NEW="$(cat <<SWIFT
// Generated by scripts/gen-buildinfo.sh; do not edit by hand.
public enum BuildInfo {
    public static let version = "$VERSION"
    public static let build = "$BUILD"
    public static let sha = "$SHA"
    public static let date = "$DATE"
    public static var versionString: String { "\(version) (\(build)) \(sha)" }
}
SWIFT
)"
# Compare without the date line so an unchanged tree does not trigger a rebuild.
if [ -f "$OUT" ] && diff -q <(grep -v 'date =' "$OUT") <(echo "$NEW" | grep -v 'date =') >/dev/null; then
  exit 0
fi
echo "$NEW" > "$OUT"
echo "▸ BuildInfo $VERSION ($BUILD) $SHA"
